function sizeBand(bytes, smallLimit, mediumLimit) {
  if (
    !Number.isSafeInteger(smallLimit) ||
    smallLimit < 0 ||
    !Number.isSafeInteger(mediumLimit) ||
    mediumLimit <= smallLimit
  ) {
    throw new Error("Enter nonnegative byte limits in increasing order");
  }
  if (!Number.isSafeInteger(bytes) || bytes < 0)
    throw new Error("The attachment did not report its byte size");
  if (bytes > mediumLimit) return "large";
  if (bytes > smallLimit) return "medium";
  return "small";
}

export default ({ events, smallBytes, mediumBytes, folderId }) => {
  sizeBand(0, smallBytes, mediumBytes);
  if (!folderId || folderId === "YOUR_DRIVE_FOLDER_ID")
    throw new Error("Configure a writable Drive folder ID");
  const seen = new Set();
  const messages = [];
  for (const event of events) {
    if (typeof event.messageId !== "string" || !event.messageId)
      throw new Error("Invalid Gmail message ID");
    if (!seen.has(event.messageId)) messages.push({ messageId: event.messageId });
    seen.add(event.messageId);
  }
  return { messages, smallBytes, mediumBytes, folderId };
};

