function sizeBand(bytes, smallLimit, mediumLimit) {
  if (
    !Number.isSafeInteger(smallLimit) ||
    smallLimit < 0 ||
    !Number.isSafeInteger(mediumLimit) ||
    mediumLimit <= smallLimit
  ) {
    throw new Error("Enter nonnegative byte limits in increasing order");
  }
  if (!Number.isSafeInteger(bytes) || bytes < 0)
    throw new Error("The attachment did not report its byte size");
  if (bytes > mediumLimit) return "large";
  if (bytes > smallLimit) return "medium";
  return "small";
}

function planAttachments(messageId, receivedId, attachments, payload, smallLimit, mediumLimit) {
  if (
    receivedId !== messageId ||
    !Array.isArray(attachments) ||
    !payload ||
    typeof payload !== "object"
  ) {
    throw new Error("Gmail did not return the requested full message");
  }
  sizeBand(0, smallLimit, mediumLimit);
  const inlineParts = new Map();
  const stack = [payload];
  while (stack.length) {
    const part = stack.pop();
    if (!part || typeof part !== "object") throw new Error("Invalid Gmail MIME part");
    if (typeof part.partId === "string" && typeof part.body?.data === "string") {
      if (inlineParts.has(part.partId))
        throw new Error("Ambiguous attachment part ID in the Gmail message");
      inlineParts.set(part.partId, part.body);
    }
    if (Array.isArray(part.parts)) stack.push(...part.parts);
  }

  const ready = [];
  const recorded = new Set();
  for (const [index, attachment] of attachments.entries()) {
    const { filename, mimeType, attachmentId, partId, size } = attachment;
    if (sizeBand(size, smallLimit, mediumLimit) !== "medium") continue;
    if (typeof filename !== "string" || typeof mimeType !== "string")
      throw new Error("Invalid attachment name or MIME type");
    const identity = attachmentId ? "external:" + attachmentId : "inline:" + partId;
    if (recorded.has(identity))
      throw new Error("Ambiguous attachment identity in the Gmail message");
    recorded.add(identity);
    let data = null;
    if (!attachmentId) {
      const part = inlineParts.get(partId);
      if (!part || part.size !== size)
        throw new Error("Cannot match the inline attachment to its Gmail MIME part");
      data = part.data;
    }
    ready.push({
      messageId,
      attachmentId: attachmentId || null,
      size,
      partId,
      name: filename.trim() || "attachment-" + (index + 1),
      mimeType: mimeType.trim() || "application/octet-stream",
      data,
    });
  }
  return ready;
}

export default ({ messageId, receivedId, attachments, payload, smallBytes, mediumBytes }) => ({
  attachments: planAttachments(
    messageId,
    receivedId,
    attachments,
    payload,
    smallBytes,
    mediumBytes,
  ),
});

