export default ({ messageId, attachments, previous }) => {
  const index = previous?.messageId === messageId ? previous.index + 1 : 0;
  const attachment = attachments[index];
  return {
    cursor: { messageId, index },
    attachment: attachment ?? null,
    more: Boolean(attachment),
    external: Boolean(attachment?.attachmentId),
    messageId,
    attachmentId: attachment?.attachmentId ?? "unused",
    filename: attachment?.name ?? "unused",
    mimeType: attachment?.mimeType ?? "application/octet-stream",
    size: attachment?.size ?? 0,
  };
};

