function matchTransit(copy, attachment) {
  if (
    copy.messageId !== attachment.messageId ||
    copy.attachmentId !== attachment.attachmentId ||
    copy.filename !== attachment.name ||
    copy.mimeType !== attachment.mimeType ||
    copy.sizeBytes !== attachment.size ||
    !/^https:\/\/[^\s/?#]+\//i.test(copy.transitUrl)
  ) {
    throw new Error("Gmail did not return the selected attachment");
  }
  return copy.transitUrl;
}

export default ({ attachment, ...copy }) => ({ url: matchTransit(copy, attachment) });

