function decodeInline(data) {
  if (typeof data !== "string" || !/^[A-Za-z0-9_-]+={0,2}$/.test(data) || data.length % 4 === 1) {
    throw new Error("Invalid Gmail base64url attachment encoding");
  }
  const decoded = atob(data.replaceAll("-", "+").replaceAll("_", "/"));
  return Uint8Array.from(decoded, (byte) => byte.charCodeAt(0));
}

function encodeBytes(bytes) {
  let result = "";
  for (let offset = 0; offset < bytes.length; offset += 12288) {
    result += btoa(String.fromCharCode(...bytes.subarray(offset, offset + 12288)));
  }
  return result;
}

export default async ({ attachment, artifact, folderId }, context) => {
  const bytes = attachment.attachmentId
    ? await context.artifact.open(artifact)
    : decodeInline(attachment.data);
  if (bytes.length !== attachment.size)
    throw new Error("The downloaded attachment does not match its Gmail byte count");
  return {
    name: attachment.name,
    mimeType: attachment.mimeType,
    parents: [folderId],
    contentBase64: encodeBytes(bytes),
    expected: {
      name: attachment.name,
      mimeType: attachment.mimeType,
      size: attachment.size,
      folderId,
    },
  };
};

