function confirmDriveFile(file, name, mimeType, folder, size) {
  if (
    typeof file?.id !== "string" ||
    !file.id ||
    file.name !== name ||
    file.mimeType !== mimeType ||
    !Array.isArray(file.parents) ||
    !file.parents.includes(folder) ||
    (file.size !== undefined && file.size !== null && String(file.size) !== String(size))
  ) {
    throw new Error(
      "Drive did not confirm the expected attachment and destination. Review Drive before replaying.",
    );
  }
  return file.id;
}

export default ({ id, name, mimeType, parents, sizeBytes, expected }) => ({
  fileId: confirmDriveFile(
    { id, name, mimeType, parents, size: sizeBytes },
    expected.name,
    expected.mimeType,
    expected.folderId,
    expected.size,
  ),
});
